<body> <?$TitleMod ="Roles de M&oacute;dulos";$Table = "ModuloSite";$Key = "IDModuloSite";$MOD = "ListModulos";$TABsel = 2;$array_permiso = array("1"=>"acceso denegado","2"=>"solo lectura","3"=>"lectura - escritura");		$permisos = get_permiso($ID_Usuario,$m,$Table);if($permisos[0] >= 2){		switch (nvl($action)) {			case "list" :				if(isset($_GET['listar'])) 						$listar = $_GET['listar'];						$sql = make_qry_string($HTTP_GET_VARS);					if(!empty($_GET['QryString'])) 						$sql = make_qry_string($HTTP_GET_VARS);					list_r($sql,$listar);			break;			case "edit":				print_form($id,"update","Actualizar $TitleMod","Realizar Cambios");			break ;			case "update" :				$frm= $HTTP_POST_VARS;				load_permisos($frm);				print_form($id,"update","Actualizar $TitleMod","Realizar Cambios");			break;			default : 					list_r();			break;				} // End switch}//end if(permisos[0] > 2)else	echo Mensaje_Info("No tiene Permisos Suficientes","col2");function load_permisos($frm){	Global $Nombre_Usuario,$idnot,$id;	$now=fecha()." ".hora();	foreach($frm[Permiso] AS $key=>$val){		if($frm[IDSeccionSite]!=-1)			$qry_existe = db_query("SELECT IDPermisos FROM Permisos WHERE IDGrupoUsuarios='$idnot' AND IDModuloSite = '$id' AND IDSeccionSite = '$key'");		else			$qry_existe = db_query("SELECT IDPermisos FROM Permisos WHERE IDGrupoUsuarios='$idnot' AND IDModuloSite = '$id' AND IDSeccionSite = '0'");		$existe = db_num_rows($qry_existe);		if($existe){			$r = db_fetch_object($qry_existe);			$sql_perm = "			UPDATE Permisos SET IDGrupoUsuarios='$idnot', 								IDModuloSite='$id', 								IDSeccionSite='$key', 								SeccionSite_name='',								Permiso='$val',  								UsuarioTrEd='$Nombre_Usuario',								FechaTrEd='$now' 			WHERE IDPermisos='$r->IDPermisos' 			";			db_query($sql_perm);		}		else{			$IDPermiso = get_maxID("Permisos","IDPermisos");					$sql_perm = "				INSERT INTO Permisos (IDPermisos, IDGrupoUsuarios, IDModuloSite, IDSeccionSite, SeccionSite_name,Permiso,  UsuarioTrCr,  FechaTrCr) 						  VALUES('$IDPermiso','$idnot','$id','$key','$frm[SeccionSite_name]','$val','$Nombre_Usuario','$now')			";			db_query($sql_perm);		}	}	window_alert("Registro Actualizado correctamente ");}/*******************************************************************************************		funtcion Print_form*******************************************************************************************/function print_form($id="",$newmode,$title,$submit_caption) {	GLOBAL $TitleMod,$Table,$MOD,$Key,$dir_img, $folder_img_directorio,$imagedir,$strcript,$array_nivel,$TableJoin;	GLOBAL $verdir_w,$verdir_h,$options,$action,$array_permiso,$idnot;	$Table = "Permisos";	$Key = "IDPermisos";	$qid = db_query(" SELECT * FROM $Table WHERE $Key = '$id' ");	$r = db_fetch_object($qid);?><?	include("directorio/menugrupo.php");		?>	<script>		function CheckAll( value )		{	 			for (var i=0;i< document.frm.elements.length;i++)			{				var e = document.frm.elements[i];								if (e.value == value)					e.checked = !e.checked;			}		}	</script>		<table cellspacing='0' cellpadding='2' border='0'  width='454' bgcolor='#FFFFFF'>		<tr>			<td class=nav width=76%>&nbsp;&nbsp;&nbsp;&nbsp;<img src=images/usrperm.png border=0> 			<a href="./?mod=<%=$MOD%>&idnot=<%=$idnot%>">Administrar <% echo $TitleMod%></a> </td>		</tr>	</table>		<?		include("Permisos/menugrupo.php");			?>	<form name="frm" action="" method="post" enctype="multipart/form-data" <%if($newmode!="delete"){%>onsubmit=" return validarModulo(); return EvaluaReg(this,Check);"<%}%>>		<table cellpadding=0 cellspacing=0 width=600>			<tr>				<td>					<table width=100% class=bordertable>									<tr class="titlemedium" height="22">										<td colspan="4" height="22" class=maintitle><?=$TitleMod?></td>									</tr>									<tr class="titlemedium" height="22">								<td>									Tabla								</td>								<td class="titlemedium">									<a href="javascript:;" onclick="CheckAll(1)">Acceso Denegado</a>								</td>								<td class="titlemedium">									<a href="javascript:;" onclick="CheckAll(2)">Solo Lectura</a>								</td>								<td class="titlemedium">									<a href="javascript:;" onclick="CheckAll(3)">Lectura - Escritura</a>								</td>							</tr>						<%						$sql_tablas = "SELECT T.Descripcion, T.IDTabla, MT.* 										FROM ModuloSite M,ModuloSite_Tabla MT, Tabla T 										WHERE MT.IDModulosite = '$id' AND T.IDtabla = MT.IDTabla 										GROUP BY MT.IDTabla ORDER BY T.Descripcion";						$qry_Modulo = db_query($sql_tablas);												 while ($Modulo = db_fetch_object($qry_Modulo) ) {							$class = repetition()?"row1":"row2";															$PermisoSel = get_field("Permisos","Permiso","IDSeccionSite",$Modulo->IDTabla."' AND IDModuloSite = '$id' AND IDGrupoUsuarios = '$idnot");							%>						<tr class=<?=$class?>>							<td>								&nbsp;&nbsp;<% echo "&nbsp;&nbsp;&nbsp; ".$Modulo->Descripcion; %>							</td>							<td align="center"><input type="radio" name="Permiso[<%=$Modulo->IDTabla%>]" value="1" <%if($PermisoSel==1 || !$PermisoSel)echo"checked"%>></td>							<td align="center"><input type="radio" name="Permiso[<%=$Modulo->IDTabla%>]" value="2" <%if($PermisoSel==2)echo"checked"%>></td>							<td align="center"><input type="radio" name="Permiso[<%=$Modulo->IDTabla%>]" value="3" <%if($PermisoSel==3)echo"checked"%>></td>						</tr>						<%							//} // End while Seccion						} // End while Modulo%>					</table>													<tr class=titlemedium>							<td align="center">					<input type="hidden" name="mod" value="<?=$MOD?>">					<input type="hidden" name="id_perm" value="-1">					<input type=hidden name=ID value="<? echo $r->$Key ?>"> 					<input type=hidden name=action value="<?=$newmode?>"> 					<input type=submit name=submit value="<? echo $submit_caption ?>" class=submit>				</td>						</tr>		</table>		</form>	<?}// End function print_form()/*******************************************************************************************		funcion Listar*******************************************************************************************/	function list_r($sql="",$listar){		Global $TitleMod,$MOD,$Key,$k,$options,$idnot;		$Table="ModuloSite";		$Key="IDModuloSite";				if(empty($sql))	 	$sql =  "SELECT * FROM $Table  ";		$nav = new buildNav;		$nav->offset = 'offset';   		$nav->number_type = 'number';   		if(!isset($listar))   			$nav->limit = 20;   		else   			$nav->limit = $listar;   		$nav->execute($sql,$dblink);		$total_records =  $nav->total_result;		$rows = $nav->rows;		$result = $nav->sql_result;		$row = $offset;		$startrow = $offset + 1;		$finalrow = ($row * $nav->limit) + $rows;		 	$pages = $nav->show_num_pages('&laquo;','&laquo; prev','&raquo;','next &raquo;','|','class=navvar');   // show pages				$info = $nav->show_info(); ?><?	include("Permisos/menugrupo.php");				if($rows > 0){		?>	<table width=600  cellpadding=0 cellspacing=0 class=bordertable>						<tr>						<td class=maintitle><% echo "Se encontraron $total_records registro(s) Mostrando del $startrow al $finalrow ";%></td>					</tr>	<tr><td><table width=600 border=0 cellspacing=1 cellpadding=0>						<? if($_GET['in_order']=="ASC" || $_GET['in_order']==""){								$img="down.png";								$order="DESC";							}else if($_GET['in_order']=="DESC"){								$img="up.png";								$order="ASC";							}														?><tr>						<td align=center  class=titlemedium valign=middle bgcolor=#DBEAF5 width=69>Editar</td>						<td class=titlemedium nowrap><a href='<? echo "?mod=$MOD&field=".$_GET['field']."&QryString=".$_GET['QryString']."&order_by=NombreModulo&table=ModuloSite&idnot=$idnot&in_order=".$order."&listar=".$nav->limit."&action=list&submit=Buscar"; ?>'>Modulo</a><a style="color: #3A4F6C;text-decoration: none" href='<? echo "?mod=$MOD&field=".$_GET['field']."&QryString=".$_GET['QryString']."&order_by=NombreModulo&table=ModuloSite&idnot=$idnot&in_order=".$order."&listar=".$nav->limit."&action=list&submit=Buscar"; ?>'>&nbsp;<? if($_GET['order_by']=="NombreModulo"){?><img src="images/<?=$img?>" border=0><?}?></a></td>						<? while($r = db_fetch_object($result)){						$class = repetition()?"row1":"row2";?><tr>						<td align=center valign=middle nowrap width=50 class=<?=$class?>>						<a href="./?mod=<%=$MOD%>&action=edit&id=<%=$r->$Key %>&idnot=<%=$idnot %>"><img src="images/edit.gif" alt="" border="0"></a></td>						<td nowrap class=<?=$class?>><? echo $r->NombreModulo ?></td>					</tr><? } // END for?><tr>						<td class=texto bgcolor=#DBEAF5 colspan=3 nowrap>	<?		print $pages;		?>		</td>					</tr>		</table></td></tr></table>	<? 			}// End if$rowselse	echo "<br><br><p class=subtitle align=center><b>No existen registros en  $TitleMod </b></p><br>";}// Enf function list()				/*******************************************************************************************		funcion filtrar*******************************************************************************************/	function filtrar(){	Global $dblink,$total_records,$row,$numtoshow,$MOD,$idnot;?>	<form name="frm" action="./" method="get" onsubmit="return valbuscar(document.frm)">			<tr>				<td class="titlemedium" align="center" colspan=8>					<select name="field" id="Buscar Por" class="popup">						<option value="">Buscar Por</option>						<option value="NombreModulo">Modulo</option>					</select> <input type="text" size="20" name="QryString" id="Buscar Por" class="post">										ordenar por <select name="order_by" class="popup">						<option value="NombreModulo">Modulo</option>											</select><br> de forma <select name="in_order" class="popup">						<option value="ASC">Ascendente</option>						<option value="DESC">Descendente</option>					</select>										Listar <select name="listar" class="popup">									<option value="10">